    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    if value is None:
        return None
    # Ensure the value behaves like a timedelta
    if not hasattr(value, "total_seconds"):
        return None
    try:
        return str(value)
    except Exception:
        return None

