def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    try:
        # Use isoformat to get a standard string representation,
        # which includes microseconds and timezone if present.
        return value.isoformat()
    except AttributeError:
        raise TypeError(f"Expected a time-like object, got {type(value).__name__}")

