def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    # Basic validation: ensure the object has the expected attributes
    required_attrs = ('lat', 'lon', 'time')
    if not all(hasattr(value, attr) for attr in required_attrs):
        raise TypeError(
            f"Expected a Point instance with attributes {required_attrs}, got {type(value).__name__}"
        )

    try:
        # Convert latitude and longitude to float (in case they are not already)
        lat = float(value.lat)
        lon = float(value.lon)

        # Convert time to ISO 8601 string if it supports isoformat, otherwise fallback to str
        time_attr = value.time
        if hasattr(time_attr, "isoformat"):
            time_str = time_attr.isoformat()
        else:
            time_str = str(time_attr)

        return {"lat": lat, "lon": lon, "time": time_str}
    except Exception as exc:
        raise ValueError(f"Failed to dehydrate Point: {exc}") from exc

