    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Helper to get all values and keys if available
    def _get_all():
        if hasattr(self, "values") and callable(self.values):
            return list(self.values()), list(self.keys())
        if hasattr(self, "_items"):
            return list(self._items), list(range(len(self._items)))
        raise AttributeError("Object does not expose values or _items")

    # If no keys specified, return all values
    if not keys:
        all_vals, _ = _get_all()
        return all_vals

    # Prepare base lists
    all_vals, all_keys = _get_all()
    result = []

    for key in keys:
        # Accept integer indices
        if isinstance(key, int):
            try:
                result.append(all_vals[key])
            except IndexError:
                raise IndexError(f"Index {key} out of range")
            continue

        # Accept string keys
        if isinstance(key, str):
            if hasattr(self, "__getitem__") and key in self:
                result.append(self[key])
            else:
                raise KeyError(f"Key '{key}' not found")
            continue

        # Unsupported key type
        raise TypeError(f"Unsupported key type: {type(key).__name__}")

    return result

