def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Assume the record stores values in a list `self._values`
    # and field names to indices in a dict `self._keys` (name -> index).
    if not hasattr(self, "_values") or not hasattr(self, "_keys"):
        raise AttributeError("Record object must have _values and _keys attributes")

    values = self._values
    name_to_index = self._keys
    # Build reverse mapping index -> name for quick lookup
    index_to_name = {idx: name for name, idx in name_to_index.items()}

    result = {}

    # If no keys specified, return all fields
    if not keys:
        for name, idx in name_to_index.items():
            # Guard against missing indices
            if 0 <= idx < len(values):
                result[name] = values[idx]
            else:
                result[name] = None
        return result

    for key in keys:
        if isinstance(key, int):
            # Index-based lookup
            if key < 0 or key >= len(values):
                raise IndexError(f"Index {key} out of bounds for record of length {len(values)}")
            name = index_to_name.get(key)
            if name is not None:
                result[name] = values[key]
            else:
                # Index exists but no name mapping; use a placeholder name
                result[f"index_{key}"] = values[key]
        elif isinstance(key, str):
            # Name-based lookup
            if key in name_to_index:
                idx = name_to_index[key]
                if 0 <= idx < len(values):
                    result[key] = values[idx]
                else:
                    result[key] = None
            else:
                # Key not present in record
                result[key] = None
        else:
            # Unsupported key type; ignore or raise
            raise TypeError(f"Unsupported key type: {type(key).__name__}")
    return result

