    if fields is None:
        fields = []
    try:
        iter(fields)
    except TypeError:
        raise TypeError(f"fields must be an iterable, got {type(fields).__name__}")
    field_names = []
    for f in fields:
        if not isinstance(f, str):
            raise TypeError(f"Field names must be strings, got {type(f).__name__}")
        if not f.isidentifier():
            raise TypeError(f"Invalid field name: {f!r}")
        if f in {"False", "None", "True", "and", "as", "assert", "break", "class",
                 "continue", "def", "del", "elif", "else", "except", "finally",
                 "for", "from", "global", "if", "import", "in", "is", "lambda",
                 "nonlocal", "not", "or", "pass", "raise", "return", "try",
                 "while", "with", "yield"}:
            raise TypeError(f"Field name cannot be a keyword: {f!r}")
        if f in field_names:
            raise TypeError(f"Duplicate field name: {f!r}")
        field_names.append(f)

    # Validate srid_map
    if srid_map is None:
        srid_map = {}
    if not isinstance(srid_map, dict):
        raise TypeError(f"srid_map must be a dict, got {type(srid_map).__name__}")

    # Prepare the namespace for the new subclass
    namespace = {"__module__": globals().get("__name__", "__main__"),
                 "__doc__": f"Point subclass {name} with fields {field_names}",
                 "SRID_MAP": srid_map}

    # Add annotations and default values for each field
    annotations = {}
    for f in field_names:
        annotations[f] = "typing.Any"  # Use a string to avoid importing typing
        namespace[f] = None
    if annotations:
        namespace["__annotations__"] = annotations

    # Attempt to create the subclass
