        base_cls = globals()["Point"]
    except KeyError:
        raise NameError("Base class 'Point' is not defined in the current context")

    try:
        new_cls = type(name, (base_cls,), namespace)
    except TypeError as exc:
        raise TypeError(f"Failed to create subclass {name!r}: {exc}") from exc

    return new_cls

