def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    # Validate parameters
    if not isinstance(maxsize, int) or maxsize < 0:
        raise ValueError("maxsize must be a non-negative integer")
    if not isinstance(ttl, (int, float)) or ttl < 0:
        raise ValueError("ttl must be a non-negative number")
    if not callable(timer):
        raise ValueError("timer must be a callable returning a monotonic time")
    if not isinstance(typed, bool):
        raise ValueError("typed must be a boolean")

    def decorator(func):
        cache = OrderedDict()

        @wraps(func)
        def wrapper(*args, **kwargs):
            # Build cache key
            try:
                if typed:
                    key = args + tuple(type(v) for v in args) + tuple(sorted(kwargs.items()))
                else:
                    key = args + tuple(sorted(kwargs.items()))
            except Exception as exc:
                # If key construction fails, fall back to no caching
                return func(*args, **kwargs)

            now = timer()
            # Check cache hit
            if key in cache:
                value, expire = cache[key]
                if expire > now:
                    # Move to end to mark as recently used
                    cache.move_to_end(key)
                    return value
                else:
                    # Expired entry
                    del cache[key]

            # Compute result
            result = func(*args, **kwargs)
            expire = now + ttl
            cache[key] = (result, expire)
            cache.move_to_end(key)

            # Enforce maxsize
            if maxsize and len(cache) > maxsize:
                cache.popitem(last=False)

            return result

        return wrapper

    return decorator

