def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    if maxsize <= 0:
        # No caching
        def decorator(func):
            return func
        return decorator

    def decorator(func):
        cache = {}
        freq = {}
        order = {}  # key -> insertion order index
        counter = 0  # incremental counter for insertion order

        def make_key(args, kwargs):
            if typed:
                key = args + tuple(kwargs.items()) + tuple(type(v) for v in args) + tuple(type(v) for v in kwargs.values())
            else:
                key = args + tuple(kwargs.items())
            return key

        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            if key in cache:
                freq[key] += 1
                return cache[key]
            # compute value
            result = func(*args, **kwargs)
            # add to cache
            cache[key] = result
            freq[key] = 1
            order[key] = counter
            nonlocal counter
            counter += 1
            # evict if necessary
            if len(cache) > maxsize:
                # find min frequency
                min_freq = min(freq.values())
                # find oldest key among those with min_freq
                oldest_key = None
                oldest_order = None
                for k in cache:
                    if freq[k] == min_freq:
                        if oldest_order is None or order[k] < oldest_order:
                            oldest_order = order[k]
                            oldest_key = k
                if oldest_key is not None:
                    del cache[oldest_key]
                    del freq[oldest_key]
                    del order[oldest_key]
            return result

        return wrapper

    return decorator

