def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    storage = self.storage
    try:
        if key in storage:
            return storage[key]
        else:
            storage[key] = default
            # Mark the storage as changed if it supports persistence
            if hasattr(storage, "_p_changed"):
                storage._p_changed = True
            return default
    except TypeError as exc:
        # key is not hashable
        raise TypeError(f"setdefault: key {key!r} is not hashable") from exc
    except Exception as exc:
        # Re-raise any other unexpected exception
        raise exc

