def _reset_logging(cls):
    """Reset"""
    try:
        root = logging.getLogger()
        # Remove all handlers from the root logger
        for handler in root.handlers[:]:
            try:
                root.removeHandler(handler)
                handler.close()
            except Exception:
                # Ignore errors while removing handlers
                pass
        # Reset the root logger level to the default
        root.setLevel(logging.WARNING)
        # Reconfigure basic logging configuration
        logging.basicConfig(level=logging.WARNING)
    except Exception:
        # Silently ignore any errors that occur during reset
        pass

