def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if classes is None:
        raise TypeError("classes must be an iterable of classes")
    result = []
    seen = set()
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError(f"Expected a class, got {type(cls).__name__}")
        if cls in seen:
            continue
        # Skip if cls is subclass of any already in result
        if any(issubclass(cls, existing) for existing in result):
            continue
        # Remove any existing classes that are subclasses of cls
        result = [existing for existing in result if not issubclass(existing, cls)]
        result.append(cls)
        seen.add(cls)
    return result

