def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    try:
        # Reset context
        self.context = {}

        # Reinitialize bins
        if hasattr(self, "initial_value") and self.initial_value is not None:
            # If bins length is known, replicate the initial value
            bins_len = getattr(self, "bins_len", 0)
            self.bins = [self.initial_value] * bins_len
        else:
            # Fall back to make_bins if available
            make_bins = getattr(self, "make_bins", None)
            if callable(make_bins):
                self.bins = make_bins()
            else:
                # If no method to create bins, start with an empty list
                self.bins = []

        # Optional: reset other histogram metadata if present
        for attr in ("total_count", "min_value", "max_value",
                     "start_time_stamp_msec", "end_time_stamp_msec"):
            if hasattr(self, attr):
                setattr(self, attr, None if attr != "total_count" else 0)

    except Exception as exc:
        raise RuntimeError(f"Failed to reset histogram: {exc}") from exc

