def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    # Validate separator
    if not isinstance(separator, str):
        raise TypeError("separator must be a string")
    # Validate header
    if header is not None and not isinstance(header, str):
        raise TypeError("header must be a string or None")

    lines = []

    # Add header if provided
    if header is not None:
        lines.append(header)

    for point in self:
        # Try to unpack point into coordinate and value
        try:
            coordinate = point.coordinate
            value = point.value
        except AttributeError:
            # Assume point is a tuple or list
            try:
                coordinate, value = point
            except Exception:
                # Skip invalid point
                continue

        # Prepare coordinate parts
        if isinstance(coordinate, (str, bytes)):
            coord_parts = [coordinate]
        elif hasattr(coordinate, "__iter__"):
            coord_parts = list(coordinate)
        else:
            coord_parts = [coordinate]

        # Prepare value parts
        if value is None:
            val_parts = []
        elif isinstance(value, (str, bytes)):
            val_parts = [value]
        elif hasattr(value, "__iter__"):
            val_parts = list(value)
        else:
            val_parts = [value]

        # Convert all parts to string
        try:
            line_parts = [str(part) for part in coord_parts + val_parts]
        except Exception:
            # Skip point if conversion fails
            continue

        lines.append(separator.join(line_parts))

    return "\n".join(lines) + ("\n" if lines else "")

