def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Validate input
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")
    # Construct the expected error variable name
    err_var_name = f"{coord_name}_err"
    # If the error variable is not present, return an empty list
    if not hasattr(self, "_variables") or err_var_name not in self._variables:
        return []
    err_var = self._variables[err_var_name]
    # Extract the underlying array of error values
    try:
        if hasattr(err_var, "values"):
            err_values = err_var.values
        else:
            err_values = np.asarray(err_var)
    except Exception:
        # If conversion fails, return empty list
        return []
    # Ensure we have a 1‑D array
    if err_values.ndim != 1:
        raise ValueError(f"Error array for '{coord_name}' must be 1‑D")
    # Determine indices where the error is defined (non‑NaN and non‑zero)
    try:
        mask = ~np.isnan(err_values) & (err_values != 0)
    except Exception:
        # Fallback: consider only non‑NaN values
        mask = ~np.isnan(err_values)
    return np.where(mask)[0]

