def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    import numpy as np

    # Convert inputs to numpy arrays
    try:
        bins_arr = np.asarray(bins)
    except Exception as exc:
        raise TypeError("bins must be array-like") from exc

    # Handle 1D edges or list/tuple of edges for multi-dimensional histograms
    if isinstance(edges, (list, tuple)):
        # Multi-dimensional case
        try:
            edges_list = [np.asarray(e) for e in edges]
        except Exception as exc:
            raise TypeError("each element of edges must be array-like") from exc

        # Compute widths for each dimension
        widths_list = [np.diff(e) for e in edges_list]
        # Build a grid of widths
        try:
            grid = np.meshgrid(*widths_list, indexing='ij')
        except Exception as exc:
            raise ValueError("failed to create width grid from edges") from exc
        # Product of widths across dimensions gives the bin volume
        widths_grid = np.prod(np.stack(grid, axis=-1), axis=-1)
        widths_flat = widths_grid.ravel()
        bins_flat = bins_arr.ravel()

        if len(bins_flat) != len(widths_flat):
            raise ValueError("Number of bins does not match product of edge intervals")

        return np.sum(bins_flat * widths_flat)

    else:
        # 1D case
        try:
            edges_arr = np.asarray(edges)
        except Exception as exc:
            raise TypeError("edges must be array-like") from exc

        if edges_arr.ndim != 1:
            raise ValueError("edges must be a 1-D array or list of arrays")

        if len(edges_arr) < 2:
            raise ValueError("edges must contain at least two values")

        if bins_arr.ndim != 1:
            raise ValueError("bins must be a 1-D array")

        if len(bins_arr) != len(edges_arr) - 1:
            raise ValueError("Number of bins must be one less than number of edges")

        widths = np.diff(edges_arr)
        return np.sum(bins_arr * widths)

