def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # Validate inputs
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both d1 and d2 must be dictionaries")
    if not isinstance(level, int):
        raise TypeError("level must be an integer")
    # Normalize level: treat any negative value other than -1 as infinite
    if level < -1:
        level = -1

    try:
        result = {}
        for key, val1 in d1.items():
            if key not in d2:
                # Key only in d1
                result[key] = val1
            else:
                val2 = d2[key]
                if val1 == val2:
                    # Same value, skip
                    continue
                # Values differ
                if isinstance(val1, dict) and isinstance(val2, dict):
                    # Both are dicts: recurse if allowed
                    if level == 0:
                        # No recursion allowed at this depth
                        result[key] = val1
                    else:
                        sublevel = level - 1 if level > 0 else -1
                        subdiff = difference(val1, val2, sublevel)
                        if subdiff:
                            result[key] = subdiff
                else:
                    # At least one value is not a dict; include val1
                    result[key] = val1
        return result
    except RecursionError as e:
        raise RuntimeError("Maximum recursion depth exceeded while computing difference") from e
    except Exception as e:
        # Re-raise any other exception with context
        raise RuntimeError(f"Error computing difference: {e}") from e

