def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Validate weight
    if weight is None:
        weight = 1
    try:
        weight = np.asarray(weight)
    except Exception as exc:
        raise ValueError("weight must be numeric or array-like") from exc

    # Validate coordinate
    try:
        coord = np.asarray(coord)
    except Exception as exc:
        raise ValueError("coord must be array-like") from exc
    if coord.ndim != 1:
        raise ValueError("coord must be a 1-D array")

    # Retrieve edges
    if not hasattr(self, "edges"):
        raise AttributeError("Histogram object has no 'edges' attribute")
    edges = self.edges
    if isinstance(edges, np.ndarray):
        edges = [edges]
    else:
        try:
            edges = [np.asarray(e) for e in edges]
        except Exception as exc:
            raise ValueError("Each edge must be array-like") from exc

    if len(coord) != len(edges):
        raise ValueError("coord length does not match histogram dimensions")

    # Find bin indices
    idx = []
    for c, e in zip(coord, edges):
        if e.ndim != 1:
            raise ValueError("Each edge array must be 1-D")
        if len(e) < 2:
            raise ValueError("Edge array must contain at least two edges")
        bin_idx = np.searchsorted(e, c, side="right") - 1
        if bin_idx < 0 or bin_idx >= len(e) - 1:
            # Outside the histogram bounds; ignore
            return
        idx.append(bin_idx)

    # Increment the appropriate bin
    if not hasattr(self, "bins"):
        raise AttributeError("Histogram object has no 'bins' attribute")
    try:
        self.bins[tuple(idx)] += weight
    except Exception as exc:
        raise RuntimeError("Failed to increment histogram bin") from exc

