def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Basic validation of the input
    if app is None:
        raise ValueError("The 'app' argument must not be None.")
    if not hasattr(app, "spec"):
        raise AttributeError("The application object must have a 'spec' attribute.")
    spec = app.spec

    # Ensure the manifest is a list of resources
    if not hasattr(spec, "manifest") or not isinstance(spec.manifest, (list, tuple)):
        raise AttributeError("The application spec must contain a 'manifest' list.")
    manifest = spec.manifest

    # Ensure the observer_schema attribute exists and is a dict
    if not hasattr(spec, "observer_schema") or not isinstance(spec.observer_schema, dict):
        spec.observer_schema = {}

    # Default schema template
    default_schema_template = {
        "type": "object",
        "properties": {
            "metadata": {
                "type": "object",
                "properties": {
                    "name": {"type": "string"},
                    "namespace": {"type": "string"},
                },
                "required": ["name"],
            },
            "status": {"type": "object"},
        },
        "required": ["metadata"],
    }

    # Iterate over each resource in the manifest
    for resource in manifest:
        try:
            kind = resource.get("kind")
            if not kind:
                continue  # Skip resources without a kind
        except AttributeError:
            # Skip if resource is not a dict-like object
            continue

        # Skip if a custom observer schema already exists for this kind
        if kind in spec.observer_schema:
            continue

        # Create a copy of the default schema for this kind
        spec.observer_schema[kind] = default_schema_template.copy()

    return spec.observer_schema

