def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary")

    # Determine the spec version to use
    spec_version = getattr(self, "spec_version", None)
    if extract_spec_version:
        type_val = inventory.get("type")
        if isinstance(type_val, str):
            try:
                # Assume a mapping from type string to spec version exists
                spec_version = getattr(self, "spec_version_map", {}).get(type_val, spec_version)
            except Exception:
                # If mapping fails, fall back to the default spec_version
                pass

    errors = []

    # Validate required fields
    required_fields = getattr(self, "required_fields", [])
    for field in required_fields:
        if field not in inventory:
            errors.append(f"Missing required field: {field}")

    # Validate field types and custom validators
    field_specs = getattr(self, "field_specs", {})
    for field, spec in field_specs.items():
        if field in inventory:
            value = inventory[field]
            try:
                # If spec has a validate method, use it
                if hasattr(spec, "validate"):
                    spec.validate(value)
                else:
                    # Otherwise, assume spec is a type or tuple of types
                    if not isinstance(value, spec):
                        expected = (
                            spec.__name__
                            if isinstance(spec, type)
                            else ", ".join(t.__name__ for t in spec)
                        )
                        errors.append(
                            f"Field '{field}' expected type {expected}, got {type(value).__name__}"
                        )
            except Exception as e:
                errors.append(f"Field '{field}' validation error: {e}")

    if errors:
        raise ValueError("Inventory validation failed: " + "; ".join(errors))

    return True

