def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Validate inputs
    if not isinstance(manifest_files, dict):
        raise TypeError("manifest_files must be a dict mapping filenames to digests")
    if digests_used is None:
        digests_used = set()
    else:
        try:
            digests_used = set(digests_used)
        except TypeError:
            raise TypeError("digests_used must be an iterable of digests")

    # Find any digests in the manifest that are not marked as used
    missing = [digest for digest in manifest_files.values() if digest not in digests_used]
    if missing:
        raise ValueError(f"Missing digests used: {missing}")

    return True

