    # Determine the original filename by stripping the language suffix
    original = os.path.basename(file_path)
    name, ext = os.path.splitext(original)
    # If the name ends with '-<lang>' remove it to get the original base
    suffix = f"-{lang}"
    if name.endswith(suffix):
        original_name = name[: -len(suffix)] + ext
    else:
        original_name = original

    # Initialize the renditions dictionary if it doesn't exist
    if not hasattr(self, "renditions"):
        self.renditions = {}

    # Ensure a sub-dict exists for the original file
    if original_name not in self.renditions:
        self.renditions[original_name] = {}

    # Add or overwrite the rendition for the specified language
    self.renditions[original_name][lang] = file_path

    # Return the updated mapping for the original file
    return self.renditions[original_name]

