def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    if not callable(namefunc):
        raise TypeError("namefunc must be callable")
    def inner(*args, **kwargs):
        try:
            result = namefunc(*args, **kwargs)
        except Exception as e:
            raise RuntimeError("Error calling wrapped function: {0}".format(e))
        # Convert unicode to bytes in Python 2
        try:
            try:
                if isinstance(result, unicode):
                    return result.encode()
            except NameError:
                # unicode not defined (Python 3), skip conversion
                pass
        except Exception:
            # ignore conversion errors
            pass
        return result
    return inner

