def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Validate pieces
    if not isinstance(pieces, (list, tuple)):
        raise TypeError("pieces must be a list or tuple")
    cleaned = []
    for p in pieces:
        if isinstance(p, int):
            cleaned.append(str(p))
        elif isinstance(p, str):
            if p.isdigit():
                cleaned.append(p)
            else:
                raise ValueError(f"Invalid piece '{p}' in pieces")
        else:
            raise TypeError(f"Piece {p!r} is not int or str")
    # Normalize style
    if not isinstance(style, str):
        raise TypeError("style must be a string")
    style = style.lower()
    # Render according to style
    if style == "short":
        # drop trailing zeros
        while cleaned and cleaned[-1] == "0":
            cleaned.pop()
        return ".".join(cleaned) if cleaned else "0"
    elif style == "full":
        return ".".join(cleaned)
    elif style == "semantic":
        return "v" + ".".join(cleaned)
    elif style == "compact":
        return "".join(cleaned)
    else:
        raise ValueError(f"Unknown style '{style}'")

