    # Normalize style
    if not isinstance(style, str):
        raise TypeError("style must be a string")
    style = style.lower()
    # Render according to style
    if style == "short":
        # drop trailing zeros
        while cleaned and cleaned[-1] == "0":
            cleaned.pop()
        return ".".join(cleaned) if cleaned else "0"
    elif style == "full":
        return ".".join(cleaned)
    elif style == "semantic":
        return "v" + ".".join(cleaned)
    elif style == "compact":
        return "".join(cleaned)
    else:
        raise ValueError(f"Unknown style '{style}'")

