def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    # Validate inputs
    if not isinstance(commands, list) or not all(isinstance(c, str) for c in commands):
        raise TypeError("commands must be a list of strings")
    if not isinstance(args, list) or not all(isinstance(a, str) for a in args):
        raise TypeError("args must be a list of strings")
    if cwd is not None and not isinstance(cwd, str):
        raise TypeError("cwd must be a string or None")
    if env is not None and not isinstance(env, dict):
        raise TypeError("env must be a dict or None")

    # Build the full command
    cmd = commands + args

    if verbose:
        print("Running command:", " ".join(cmd))

    # Prepare stderr handling
    stderr = subprocess.DEVNULL if hide_stderr else None

    # Merge environment if provided
    env_vars = os.environ.copy()
    if env:
        env_vars.update(env)

    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            stdout=subprocess.PIPE,
            stderr=stderr,
            env=env_vars,
            text=True,
            check=True,
        )
        return result.stdout
    except subprocess.CalledProcessError as e:
        raise RuntimeError(
            f"Command '{' '.join(cmd)}' failed with exit code {e.returncode}"
        ) from e
    except OSError as e:
        raise RuntimeError(
            f"Failed to execute command '{' '.join(cmd)}': {e}"
