def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Validate input types
    if not isinstance(validate_objects, bool):
        raise TypeError('validate_objects must be a bool')
    if not isinstance(check_digests, bool):
        raise TypeError('check_digests must be a bool')
    if not isinstance(show_warnings, bool):
        raise TypeError('show_warnings must be a bool')

    # Ensure storage root exists
    if not hasattr(self, '_storage_root'):
        raise AttributeError('Storage root not initialized')

    # Determine iterable of objects
    root = self._storage_root
    if isinstance(root, dict):
        objects_iter = root.values()
    elif hasattr(root, '__iter__'):
        objects_iter = root
    else:
        raise TypeError('Storage root must be an iterable or dict')

    num_objects = 0
    good_objects = 0

    for obj in objects_iter:
        num_objects += 1
        is_valid = True

        # Validate object structure if requested
        if validate_objects:
            try:
                if hasattr(obj, 'validate') and callable(obj.validate):
                    obj.validate()
                else:
                    # If no validate method, assume valid
                    pass
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f'Warning: object {obj!r} failed validation: {exc}')

        # Check digest if requested and still valid
        if check_digests and is_valid:
            try:
                if hasattr(obj, 'check_digest') and callable(obj.check_digest):
                    if not obj.check_digest():
                        is_valid = False
                        if show_warnings:
                            print(f'Warning: object {obj!r} failed digest check')
                else:
                    # No digest method; skip
                    pass
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f'Warning: object {obj!r} digest check error: {exc}')

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

