def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Validate input
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")
    if not version_dirs:
        raise ValueError("version_dirs cannot be empty")
    for vdir in version_dirs:
        if not isinstance(vdir, str):
            raise TypeError(f"Each version directory name must be a string, got {type(vdir).__name__}")

    # Ensure root inventory exists
    if not hasattr(self, "root_inventory") or not isinstance(self.root_inventory, dict):
        raise AttributeError("Instance must have a 'root_inventory' dict attribute")

    # Prepare record of differing digests
    self.different_digests = {}

    cumulative_keys = set()
    for vdir in version_dirs:
        inv_path = os.path.join(vdir, "inventory.json")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Missing inventory file for version '{vdir}' at {inv_path}")

        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                inv = json.load(f)
        except Exception as exc:
            raise ValueError(f"Failed to load inventory for version '{vdir}': {exc}")

        if not isinstance(inv, dict):
            raise ValueError(f"Inventory for version '{vdir}' must be a mapping")

        # Ensure inventory contains all entries up to this point
        if not cumulative_keys.issubset(inv.keys()):
            missing = cumulative_keys - set(inv.keys())
            raise ValueError(f"Inventory for version '{vdir}' is missing entries: {missing}")

        cumulative_keys.update(inv.keys())

        # Compare digests with root inventory
        for key, digest in inv.items():
            root_digest = self.root_inventory.get(key)
            if root_digest is None:
                continue
            if digest != root_digest:
                self.different_digests.setdefault(key, []).append(vdir)

    return self

