        except Exception as exc:
            raise TypeError("bug_ids must be an int, str, or iterable of ids") from exc
    if not ids:
        return params
    # Convert ids to a comma‑separated string for Bugzilla
    try:
        params['ids'] = ','.join(str(i) for i in ids)
    except Exception as exc:
        raise ValueError("Failed to format bug_ids for Bugzilla params") from exc
    return params

