def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not isinstance(url, str):
        raise TypeError('url must be a string')
    if not url:
        return ''
    if not url_args:
        return url
    if not isinstance(url_args, dict):
        raise TypeError('url_args must be a dict')
    import re
    result = url
    for key, value in url_args.items():
        if value is None:
            continue
        key_str = str(key)
        val_str = str(value)
        # Replace {key}
        result = re.sub(r'\{' + re.escape(key_str) + r'\}', val_str, result)
        # Replace :key
        result = re.sub(r':' + re.escape(key_str), val_str, result)
    return result

