def subclasses(cls):
    """Return all subclasses of a class, recursively."""
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class, got {type(cls).__name__}")
    seen = set()
    stack = [cls]
    while stack:
        current = stack.pop()
        try:
            subcls = current.__subclasses__()
        except Exception as exc:
            # If __subclasses__ fails, skip this branch
            continue
        for sub in subcls:
            if sub not in seen:
                seen.add(sub)
                stack.append(sub)
    return seen

