def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Validate inputs
    if string is None or alphabet is None:
        raise TypeError("Both 'string' and 'alphabet' must be provided and not None.")
    if not isinstance(string, str):
        raise TypeError(f"'string' must be a str, got {type(string).__name__}.")
    if not isinstance(alphabet, list):
        raise TypeError(f"'alphabet' must be a list of single-character strings, got {type(alphabet).__name__}.")

    if len(alphabet) == 0:
        raise ValueError("Alphabet must contain at least one character.")

    # Ensure alphabet elements are single-character strings and unique
    seen = set()
    for idx, ch in enumerate(alphabet):
        if not isinstance(ch, str) or len(ch) != 1:
            raise ValueError(f"Alphabet element at position {idx} ('{ch}') is not a single-character string.")
        if ch in seen:
            raise ValueError(f"Duplicate character '{ch}' found in alphabet.")
        seen.add(ch)

    # Build mapping from character to its numeric value
    char_to_value = {ch: i for i, ch in enumerate(alphabet)}
    base = len(alphabet)

    # Convert string to integer
    result = 0
    for pos, ch in enumerate(string):
        if ch not in char_to_value:
            raise ValueError(f"Character '{ch}' at position {pos} not found in alphabet.")
        result = result * base + char_to_value[ch]

    return result

