    parts = freq.split()
    if len(parts) != 2:
        raise ValueError(f"Cannot parse frequency: {frequency}")
    num_str, unit = parts
    try:
        num = int(num_str)
    except ValueError:
        raise ValueError(f"Invalid number in frequency: {frequency}")
    unit = unit.lower()
    unit_map = {
        'day': 'days', 'days': 'days',
        'week': 'weeks', 'weeks': 'weeks',
        'hour': 'hours', 'hours': 'hours', 'hr': 'hours', 'hrs': 'hours',
        'minute': 'minutes', 'minutes': 'minutes', 'min': 'minutes', 'mins': 'minutes',
        'second': 'seconds', 'seconds': 'seconds', 'sec': 'seconds', 'secs': 'seconds',
    }
    if unit not in unit_map:
        raise ValueError(f"Unknown time unit in frequency: {frequency}")
