def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Strings are treated specially
    if isinstance(seq, str):
        return (seq, 'string')

    # Lists and tuples are returned as-is
    if isinstance(seq, (list, tuple)):
        return (seq, 'list')

    # Try to obtain an iterator; if this fails, treat as a single element
    try:
        it = iter(seq)
    except TypeError:
        return ([seq], 'list')

    # If we get here, seq is an iterable that is not a list/tuple/string
    # Convert it to a list, optionally using a buffer size
    try:
        if bufsize is None:
            seq_list = list(seq)
        else:
            # Read in chunks of size bufsize
            seq_list = []
            while True:
                chunk = []
                for _ in range(bufsize):
                    chunk.append(next(it))
                seq_list.extend(chunk)
    except StopIteration:
        # Normal end of iterator
        pass
    except Exception:
        # Fallback: try a simple list conversion
        try:
            seq_list = list(seq)
        except Exception:
            # If conversion fails, treat as a single element
            seq_list = [seq]

    return (seq_list, 'list')

