def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Import numbers for numeric type checking
    import numbers

    # Helper to raise the custom exception
    try:
        from .exceptions import LenaValueError
    except Exception:
        # Fallback if the module path is different
        try:
            from exceptions import LenaValueError
        except Exception:
            # Define a minimal placeholder if not available
            class LenaValueError(Exception):
                pass

    # Ensure the graph has fields defined
    if not hasattr(self, "fields") or not isinstance(self.fields, (list, tuple)):
        raise AttributeError("Graph object must have a 'fields' attribute of type list or tuple.")

    if not self.fields:
        raise ValueError("Graph has no fields to rescale.")

    # Determine current scale
    current_scale = getattr(self, "_scale", None)
    if current_scale is None:
        raise LenaValueError("Current scale is unknown; cannot rescale.")

    if current_scale == 0:
        raise LenaValueError("Current scale is zero; cannot rescale.")

    # If no new scale requested, just return the current scale
    if other is None:
        return current_scale

    # Validate the new scale
    if not isinstance(other, numbers.Number):
        raise TypeError(f"Provided scale '{other}' is not a numeric value.")

    # Compute scaling factor
    factor = other / current_scale

    # Identify the last coordinate field
    last_field = self.fields[-1]

    # Rescale the data for the last field
    if hasattr(self, "data") and isinstance(self.data, dict):
        if last_field in self.data:
            try:
                self.data[last_field] = self.data[last_field] * factor
            except Exception as exc:
                raise ValueError(f"Failed to rescale data for field '{last_field}': {exc}") from exc
        else:
            raise KeyError(f"Field '{last_field}' not found in graph data.")
    else:
        raise AttributeError("Graph object must have a 'data' attribute of type dict.")

    # Rescale the errors for the last field, if present
    if hasattr(self, "errors") and isinstance(self.errors, dict):
        if last_field in self.errors:
            try:
                self.errors[last_field] = self.errors[last_field] * factor
            except Exception as exc:
                raise ValueError(f"Failed to rescale errors for field '{last_field}': {exc}") from exc
        # If errors for this field are not present, silently ignore

    # Update the internal scale value
    self._scale = other

    # Return self to allow method chaining
    return self

