def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Validate get_coordinate
    if not isinstance(get_coordinate, str):
        raise TypeError("get_coordinate must be a string")
    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

    # Validate field_names
    if not hasattr(field_names, "__iter__"):
        raise TypeError("field_names must be an iterable of strings")
    field_names = tuple(field_names)
    if len(field_names) < 2:
        raise ValueError("field_names must contain at least two elements")
    for name in field_names:
        if not isinstance(name, str):
            raise TypeError("All field_names must be strings")

    # Determine scale
    if isinstance(scale, bool):
        if scale:  # True: use histogram's scale
            scale_value = getattr(hist, "scale", None)
        else:      # False: no scale
            scale_value = None
    else:
        scale_value = scale

    # Retrieve bins and edges
    try:
        bins = getattr(hist, "bins")
    except AttributeError:
        raise AttributeError("histogram object has no 'bins' attribute")
    try:
        edges = getattr(hist, "edges")
    except AttributeError:
        raise AttributeError("histogram object has no 'edges' attribute")

    if not hasattr(bins, "__iter__"):
        raise TypeError("hist.bins must be iterable")
    if not hasattr(edges, "__iter__"):
        raise TypeError("hist.edges must be iterable")

    bins = list(bins)
    edges = list(edges)

    if len(edges) != len(bins) + 1:
        raise ValueError("Number of edges must be one more than number of bins")

    if len(bins) == 0:
        # Return an empty graph
        class Graph:
            def __init__(self, points, scale=None, field_names=None):
                self.points = points
                self.scale = scale
                self.field_names = field_names
        return Graph([], scale=scale_value, field_names=field_names)

    points = []

    for i, bin_item in enumerate(bins):
        # Determine x coordinate
        if get_coordinate == "left":
            x_coord = edges[i]
        elif get_coordinate == "right":
            x_coord = edges[i + 1]
        else:  # middle
            x_coord = (edges[i] + edges[i + 1]) / 2

        # Extract bin content
        if hasattr(bin_item, "content"):
            content = bin_item.content
        elif isinstance(bin_item, (list, tuple)):
            content = bin_item[0]
        else:
            content = bin_item

        # Compute value(s)
        if make_value is None:
            values = (content,)
        else:
            try:
                val = make_value(content)
            except Exception as exc:
                raise RuntimeError(f"make_value raised an exception for bin {i}") from exc
            if val is None:
                raise ValueError(f"make_value returned None for bin {i}")
            if isinstance(val, (list, tuple)):
                values = tuple(val)
            else:
                values = (val,)

        # Validate number of values matches field_names
        if len(values) != len(field_names) - 1:
            raise ValueError(
                f"Number of values returned by make_value ({len(values)}) "
                f"does not match number of field_names ({len(field_names)-1}) "
                f"for bin {i}"
            )

        # Build point dictionary
        point = {field_names[0]: x_coord}
        for idx, val in enumerate(values):
            point[field_names[idx + 1]] = val

        points.append(point)

    # Simple Graph class to hold the result
    class Graph:
        def __init__(self, points, scale=None, field_names=None):
            self.points = points
            self.scale = scale
            self.field_names = field_names

    return Graph(points, scale=scale_value, field_names=field_names)

