def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Validate that bases is iterable
    try:
        iter(bases)
    except TypeError:
        raise TypeError("bases must be an iterable of classes") from None

    # Helper to find the most derived metaclass between two candidates
    def _most_derived(a, b):
        if a is b:
            return a
        if issubclass(a, b):
            return a
        if issubclass(b, a):
            return b
        raise TypeError(f"metaclass conflict: {a} vs {b}")

    # If an explicit metaclass is provided, validate it
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(f"__metaclass__ must be a type, not {type(explicit_mc).__name__}")
        for base in bases:
            base_meta = type(base)
            if not issubclass(explicit_mc, base_meta):
                raise TypeError(f"__metaclass__ {explicit_mc} is not a subclass of {base_meta}")
        return explicit_mc

    # No explicit metaclass: derive from the bases
    if not bases:
        return type

    # Start with the metaclass of the first base
    meta = type(bases[0])
    for base in bases[1:]:
        meta = _most_derived(meta, type(base))
    return meta

