def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # Ensure the container is not empty
    if not hasattr(self, "_data") or not self._data:
        raise KeyError("dict is empty")

    # Determine the key with the lowest frequency
    if hasattr(self, "_freq") and isinstance(self._freq, dict):
        try:
            min_key = min(self._freq, key=lambda k: self._freq[k])
        except ValueError:
            # _freq is empty but _data is not; fall back to any key
            min_key = next(iter(self._data))
    else:
        # No frequency tracking available; pop an arbitrary key
        min_key = next(iter(self._data))

    # Remove the key from the data store
    value = self._data.pop(min_key)

    # Remove the key from the frequency map if it exists
    if hasattr(self, "_freq"):
        self._freq.pop(min_key, None)

    return (min_key, value)

