def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    try:
        cache = getattr(self, "_cache", None)
        if cache is None:
            raise AttributeError("Cache attribute _cache not found")
        # If cache is an OrderedDict, pop the first item
        if type(cache).__name__ == "OrderedDict":
            return cache.popitem(last=False)
        # If cache is a plain dict (Python 3.7+ preserves insertion order)
        if isinstance(cache, dict):
            key = next(iter(cache))
            value = cache.pop(key)
            return key, value
        # Fallback: assume a doubly linked list implementation
        head = getattr(self, "_head", None)
        tail = getattr(self, "_tail", None)
        if head is not None and tail is not None:
            node = head[2]  # first real node after head sentinel
            if node is tail:
                raise KeyError("LRU cache is empty")
            key, value = node[0], node[1]
            self._remove(node)
            return key, value
        raise AttributeError("No suitable cache structure found")
    except StopIteration:
        raise KeyError("LRU cache is empty")
    except Exception as exc:
        raise RuntimeError(f"Error popping LRU item: {exc}") from exc

