def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        return None
    # Try JSON first
    try:
        import json
        data = json.loads(document)
        subject = data.get("subject")
        links = data.get("links", [])
        # Ensure links are list of dicts with rel and href
        parsed_links = []
        for link in links:
            if isinstance(link, dict):
                rel = link.get("rel")
                href = link.get("href")
                if rel and href:
                    parsed_links.append({"rel": rel, "href": href})
        return {"subject": subject, "links": parsed_links}
    except Exception:
        # Fallback to XRD (XML)
        try:
            import xml.etree.ElementTree as ET
            root = ET.fromstring(document)
            ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
            subject_elem = root.find("xrd:Subject", ns)
            subject = subject_elem.text if subject_elem is not None else None
            links = []
            for link in root.findall("xrd:Link", ns):
                rel = link.attrib.get("rel")
                href = link.attrib.get("href")
                if rel and href:
                    links.append({"rel": rel, "href": href})
            return {"subject": subject, "links": links}
        except Exception:
            return None

