def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    Each parser specification in ``parser_dict`` may contain an ``include``
    key whose value is either a string or a list of parser names.  The
    method expands these includes by merging the referenced parser
    specifications into the current one.  The merge is performed
    recursively and circular references raise a ``ValueError``.  The
    original ``parser_dict`` is updated in place; the method returns
    ``None``.
    """
    # Cache of fully resolved specs to avoid repeated work
    resolved_cache = {}

    def _resolve(name, stack):
        """Recursively resolve a single parser spec."""
        if name in resolved_cache:
            return resolved_cache[name]
        if name in stack:
            cycle = ' -> '.join(stack + [name])
            raise ValueError(f'Circular include detected: {cycle}')
        stack.append(name)

        spec = parser_dict.get(name)
        if spec is None:
            raise KeyError(f'Parser spec "{name}" not found.')

        # Start with an empty dict that will hold the merged result
        merged = {}

        # Handle the include directive if present
        includes = spec.get('include')
        if includes:
            if isinstance(includes, str):
                includes = [includes]
            for inc_name in includes:
                inc_spec = _resolve(inc_name, stack.copy())
                merged.update(inc_spec)

        # Merge the current spec, overriding any keys from includes
        for key, value in spec.items():
            if key != 'include':
                merged[key] = value

        resolved_cache[name] = merged
        return merged

    # Resolve all specs and update the original dictionary
    for parser_name in list(parser_dict.keys()):
        try:
            resolved_spec = _resolve(parser_name, [])
            parser_dict[parser_name] = resolved_spec
        except Exception as exc:
            # Preserve original exception type and message for debugging
            raise type(exc)(f'Error resolving parser "{parser_name}": {exc}') from exc
    return None

