def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    # Retrieve the spec dictionary; if not present, use empty dict
    spec = getattr(self, 'spec', {})
    if spec is None:
        spec = {}
    # Iterate over all arguments defined in the scheme
    for arg in getattr(self, 'args', []):
        # Skip non-option objects
        if not isinstance(arg, _BaseOpt):
            continue
        # Determine the value: spec value takes precedence over default
        if arg.name in spec:
            val = spec[arg.name]
        else:
            # Use the option's default if it exists
            if not isinstance(arg.default, NoDefault):
                val = arg.default
            else:
                val = None
        # If the option is a dictionary option, resolve nested defaults
        if isinstance(arg, DictOption):
            # Ensure we have a nested scheme to work with
            nested_scheme = getattr(arg, 'scheme', None)
            if nested_scheme:
                # Recursively resolve defaults for the nested scheme
                nested_defaults = nested_scheme.get_spec_defaults()
                # Merge nested defaults with any values provided in the spec
                if isinstance(val, dict):
                    merged = {**nested_defaults, **val}
                else:
                    merged = nested_defaults
                val = merged
        defaults[arg.name] = val
    return defaults

