    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for opt in options_spec:
        # Retrieve the condition and the option name
        if isinstance(opt, dict):
            cond = opt.get('required_when')
            name = opt.get('arg') or opt.get('name')
        else:
            cond = getattr(opt, 'required_when', None)
            name = getattr(opt, 'arg', None) or getattr(opt, 'name', None)

        if cond is None or not name:
            continue

        try:
            if callable(cond):
                matched = cond(args)
            elif isinstance(cond, str):
                # Evaluate the string in a safe namespace
                matched = eval(cond, {}, {'command_name': command_name, 'args': args})
            elif isinstance(cond, bool):
                matched = cond
            else:
                raise TypeError(f"Unsupported required_when type: {type(cond)}")
        except Exception as exc:
            raise ValueError(f"Error evaluating required_when for option '{name}': {exc}") from exc

        if matched:
            required.append(name)

    return required

