def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars (each should be a dict)
    :return: The updated dictionary
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if extra_vars is None:
        return vars_dict
    if not isinstance(extra_vars, list):
        raise TypeError("extra_vars must be a list or None")
    for ev in extra_vars:
        if isinstance(ev, dict):
            vars_dict.update(ev)
        else:
            # Skip non-dict entries to avoid errors
            continue
    return vars_dict

