def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        import yaml
    except ImportError:
        yaml = None

    if not isinstance(plugin_dir, str) or not os.path.isdir(plugin_dir):
        raise ValueError(f"plugin_dir {plugin_dir!r} is not a valid directory")

    # Locate the plugin spec file
    spec_file = None
    for fname in ("plugin.json", "plugin.yaml", "plugin.yml"):
        candidate = os.path.join(plugin_dir, fname)
        if os.path.isfile(candidate):
            spec_file = candidate
            break
    if spec_file is None:
        raise FileNotFoundError("No plugin spec file found in the specified directory")

    # Load the spec file
    try:
        with open(spec_file, "r", encoding="utf-8") as f:
            if spec_file.endswith(".json"):
                data = json.load(f)
            else:
                if yaml is None:
                    raise RuntimeError("yaml module is required to parse non‑JSON plugin specs")
                data = yaml.safe_load(f)
    except Exception as exc:
        raise RuntimeError(f"Failed to load plugin spec from {spec_file!r}: {exc}") from exc

    if not isinstance(data, dict):
        raise TypeError("Plugin spec must be a dictionary at the top level")

    # Flatten nested dictionaries
    def _flatten(d, parent_key=""):
        flat = {}
        for key, value in d.items():
            new_key = f"{parent_key}.{key}" if parent_key else key
            if isinstance(value, dict):
                flat.update(_flatten(value, new_key))
            else:
                flat[new_key] = value
        return flat

    return _flatten(data)

